1	import * as fs from "node:fs";
2	import * as path from "node:path";
3	import { google, gmail_v1 } from "googleapis";
4	import { authorize } from "./gmail-auth";
5	import { summarize, OLLAMA_MODEL } from "./summarize";
6	import { mergeContact } from "./merge";
7	
8	// Slice 2 — Incremental per-contact search, READ-ONLY DRY-RUN.
9	//
10	// For each contact file passed as an argument, search Mark's Gmail for the
11	// contact's address(es), derive direction, dedup against entries already in the
12	// file, and PRINT the proposed new "Mark's Email History" entries plus the
13	// last_searched date that *would* be written. Writes nothing.
14	//
15	//   env "$(op environment read <item-id>)" npm run gmail-sync -- friends/blyth-don.md ...
16	//
17	// First run (no last_searched in frontmatter) searches all history, ignoring
18	// last_updated. Once last_searched exists it bounds the query with after:.
19	
20	const ROOT = path.resolve(__dirname, "..");
21	
22	// How far back the FIRST run reaches, per category, so an initial scan of a
23	// decades-deep mailbox doesn't take forever. Incremental runs ignore this — they
24	// are bounded by last_searched instead.
25	const YEARS_BACK: Record<string, number> = {
26	  client: 3,
27	  colleague: 3,
28	  friend: 10,
29	};
30	
31	// Safety cap so a mis-built query can't page forever; we log if we hit it.
32	const MAX_MESSAGES_PER_CONTACT = 2000;
33	
34	// Retry Gmail calls on rate-limit / transient errors with exponential backoff.
35	async function withBackoff<T>(fn: () => Promise<T>, label: string): Promise<T> {
36	  const maxRetries = 6;
37	  let delay = 500;
38	  for (let attempt = 0; ; attempt++) {
39	    try {
40	      return await fn();
41	    } catch (err: unknown) {
42	      const e = err as {
43	        code?: number;
44	        response?: { status?: number };
45	        errors?: Array<{ reason?: string }>;
46	      };
47	      const status = e.code ?? e.response?.status;
48	      const reason = e.errors?.[0]?.reason ?? "";
49	      const retryable =
50	        status === 429 ||
51	        status === 500 ||
52	        status === 503 ||
53	        (status === 403 && /rateLimit|userRateLimit|quota/i.test(reason));
54	      if (!retryable || attempt >= maxRetries) throw err;
55	      const wait = delay + Math.floor(Math.random() * 250);
56	      console.error(
57	        `  ⏳ ${label}: ${status} ${reason} — retry ${attempt + 1}/${maxRetries} in ${wait}ms`
58	      );
59	      await new Promise((r) => setTimeout(r, wait));
60	      delay = Math.min(delay * 2, 16000);
61	    }
62	  }
63	}
64	
65	// ─── Contact file parsing ────────────────────────────────────────────────────
66	
67	interface Contact {
68	  filePath: string;
69	  category: string; // client | friend | colleague
70	  firstName: string | null; // for name-led summaries
71	  emails: string[]; // lowercased
72	  lastSearched: string | null; // YYYY-MM-DD or null
73	  existingMessageIds: Set<string>; // Gmail hex ids already recorded
74	  existingLegacyKeys: Set<string>; // date|subject|direction|thread for old entries
75	}
76	
77	// Match on a path *segment* so both relative ("friends/x.md") and absolute
78	// paths work — the earlier "/friends/" substring test missed relative args.
79	function categoryFor(contactPath: string): string {
80	  const segs = contactPath.replace(/\\/g, "/").split("/");
81	  if (segs.includes("friends")) return "friend";
82	  if (segs.includes("colleagues")) return "colleague";
83	  return "client";
84	}
85	
86	function unquote(s: string): string {
87	  return s.trim().replace(/^["']|["']$/g, "").trim();
88	}
89	
90	function parseContact(contactPath: string): Contact {
91	  const abs = path.isAbsolute(contactPath)
92	    ? contactPath
93	    : path.join(ROOT, contactPath);
94	  const raw = fs.readFileSync(abs, "utf-8");
95	
96	  const fmMatch = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
97	  if (!fmMatch) throw new Error(`No YAML frontmatter in ${contactPath}`);
98	  const fmLines = fmMatch[1].split(/\r?\n/);
99	
100	  const emails: string[] = [];
101	  let lastSearched: string | null = null;
102	  let firstName: string | null = null;
103	
104	  for (let i = 0; i < fmLines.length; i++) {
105	    const line = fmLines[i];
106	    const fn = line.match(/^first_name:\s*(.+)$/);
107	    if (fn) {
108	      firstName = unquote(fn[1]) || null;
109	      continue;
110	    }
111	    const single = line.match(/^email:\s*(.+)$/);
112	    if (single) {
113	      const v = unquote(single[1]);
114	      if (v.includes("@")) emails.push(v.toLowerCase());
115	      continue;
116	    }
117	    if (/^emails:\s*$/.test(line)) {
118	      for (let j = i + 1; j < fmLines.length; j++) {
119	        const item = fmLines[j].match(/^\s*-\s*(.+)$/);
120	        if (!item) break;
121	        const v = unquote(item[1]);
122	        if (v.includes("@")) emails.push(v.toLowerCase());
123	      }
124	      continue;
125	    }
126	    const ls = line.match(/^last_searched:\s*(.+)$/);
127	    if (ls) lastSearched = unquote(ls[1]) || null;
128	  }
129	
130	  // Existing entries: collect Gmail message ids and legacy dedup keys from the
131	  // "## Mark's Email History" section only.
132	  const existingMessageIds = new Set<string>();
133	  const existingLegacyKeys = new Set<string>();
134	  const markSection = raw.split(/^##\s+Mark's Email History\s*$/m)[1];
135	  if (markSection) {
136	    // Cut it off at the next H2 (e.g. "## Email History").
137	    const section = markSection.split(/^##\s+/m)[0];
138	    let curDate = "";
139	    let curSubject = "";
140	    let curDirection = "";
141	    let curThread = "";
142	    let curMessage = "";
143	    const flushLegacy = () => {
144	      if (curSubject && !curMessage) {
145	        existingLegacyKeys.add(
146	          `${curDate}|${curSubject}|${curDirection}|${curThread}`
147	        );
148	      }
149	      curSubject = curDirection = curThread = curMessage = "";
150	    };
151	    for (const line of section.split(/\r?\n/)) {
152	      const dateM = line.match(/^###\s+(\d{4}-\d{2}-\d{2})/);
153	      if (dateM) {
154	        flushLegacy();
155	        curDate = dateM[1];
156	        continue;
157	      }
158	      const subjM = line.match(/^-\s+\*\*Subject:\*\*\s*(.+?)\s*$/);
159	      if (subjM) {
160	        flushLegacy();
161	        curSubject = subjM[1];
162	        continue;
163	      }
164	      const dirM = line.match(/^\s*-\s*Direction:\s*(.+?)\s*$/);
165	      if (dirM) curDirection = dirM[1];
166	      const thrM = line.match(/^\s*-\s*Thread:\s*(.+?)\s*$/);
167	      if (thrM) curThread = thrM[1];
168	      const msgM = line.match(/^\s*-\s*Message:\s*(.+?)\s*$/);
169	      if (msgM) {
170	        curMessage = msgM[1];
171	        existingMessageIds.add(curMessage);
172	      }
173	    }
174	    flushLegacy();
175	  }
176	
177	  return {
178	    filePath: contactPath,
179	    category: categoryFor(contactPath),
180	    firstName,
181	    emails,
182	    lastSearched,
183	    existingMessageIds,
184	    existingLegacyKeys,
185	  };
186	}
187	
188	// ─── Header helpers ──────────────────────────────────────────────────────────
189	
190	function decodeRFC2047(s: string): string {
191	  return s.replace(
192	    /=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g,
193	    (_m, charset, enc, encoded) => {
194	      try {
195	        if (enc.toUpperCase() === "B") {
196	          return Buffer.from(encoded, "base64").toString(
197	            charset.toLowerCase() === "utf-8" ? "utf-8" : "latin1"
198	          );
199	        }
200	        return encoded
201	          .replace(/_/g, " ")
202	          .replace(/=([0-9A-Fa-f]{2})/g, (_x: string, h: string) =>
203	            String.fromCharCode(parseInt(h, 16))
204	          );
205	      } catch {
206	        return encoded;
207	      }
208	    }
209	  );
210	}
211	
212	// Extract lowercased email addresses from a header value.
213	function addressesIn(headerValue: string): string[] {
214	  const out: string[] = [];
215	  const re = /[\w.+\-]+@[\w.\-]+\.\w+/g;
216	  let m: RegExpExecArray | null;
217	  while ((m = re.exec(headerValue)) !== null) out.push(m[0].toLowerCase());
218	  return out;
219	}
220	
221	function headerValue(
222	  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
223	  name: string
224	): string {
225	  const h = headers?.find((x) => (x.name ?? "").toLowerCase() === name);
226	  return h?.value ?? "";
227	}
228	
229	// ─── Direction ───────────────────────────────────────────────────────────────
230	
231	// Mark sent it (Gmail SENT label, authoritative across all of Mark's historical
232	// addresses) → "To {cat}". Else contact is the sender → "From {cat}". Else Mark
233	// is only a recipient on a thread neither he nor the contact started → "CC'd".
234	function deriveDirection(
235	  labelIds: string[],
236	  fromAddrs: string[],
237	  contactEmails: Set<string>,
238	  category: string
239	): string {
240	  if (labelIds.includes("SENT")) return `To ${category}`;
241	  if (fromAddrs.some((a) => contactEmails.has(a))) return `From ${category}`;
242	  return "CC'd";
243	}
244	
245	// ─── Proposed entry ──────────────────────────────────────────────────────────
246	
247	interface ProposedEntry {
248	  ts: number; // internalDate ms, for exact ordering within a day
249	  dateStr: string;
250	  subject: string;
251	  direction: string;
252	  threadId: string;
253	  messageId: string;
254	  link: string;
255	  summary?: string; // filled by --summarize
256	}
257	
258	function legacyKey(e: ProposedEntry): string {
259	  return `${e.dateStr}|${e.subject}|${e.direction}|${e.threadId}`;
260	}
261	
262	// ─── Gmail search ────────────────────────────────────────────────────────────
263	
264	// The lower bound for a contact's search: last_searched if we have one,
265	// otherwise the per-category first-run floor (today − N years). Returns
266	// YYYY-MM-DD.
267	function effectiveAfter(contact: Contact, today: string): string {
268	  if (contact.lastSearched) return contact.lastSearched;
269	  const years = YEARS_BACK[contact.category] ?? 3;
270	  const d = new Date(today);
271	  d.setFullYear(d.getFullYear() - years);
272	  return d.toISOString().slice(0, 10);
273	}
274	
275	function buildQuery(contact: Contact, today: string): string {
276	  const addrs = contact.emails.join(" OR ");
277	  const clauses = `(from:(${addrs}) OR to:(${addrs}) OR cc:(${addrs}))`;
278	  const after = effectiveAfter(contact, today).replace(/-/g, "/"); // YYYY/MM/DD
279	  return `after:${after} ${clauses}`;
280	}
281	
282	async function searchContact(
283	  gmail: gmail_v1.Gmail,
284	  contact: Contact,
285	  today: string
286	): Promise<{ entries: ProposedEntry[]; capped: boolean }> {
287	  const q = buildQuery(contact, today);
288	  const ids: { id: string; threadId: string }[] = [];
289	  let pageToken: string | undefined;
290	  let capped = false;
291	
292	  do {
293	    const res = await withBackoff(
294	      () =>
295	        gmail.users.messages.list({
296	          userId: "me",
297	          q,
298	          maxResults: 500,
299	          pageToken,
300	        }),
301	      "messages.list"
302	    );
303	    for (const m of res.data.messages ?? []) {
304	      if (m.id && m.threadId) ids.push({ id: m.id, threadId: m.threadId });
305	    }
306	    pageToken = res.data.nextPageToken ?? undefined;
307	    if (ids.length >= MAX_MESSAGES_PER_CONTACT) {
308	      capped = true;
309	      break;
310	    }
311	  } while (pageToken);
312	
313	  const contactEmails = new Set(contact.emails);
314	  const entries: ProposedEntry[] = [];
315	
316	  for (const { id } of ids) {
317	    const msg = await withBackoff(
318	      () =>
319	        gmail.users.messages.get({
320	          userId: "me",
321	          id,
322	          format: "metadata",
323	          metadataHeaders: ["From", "To", "Cc", "Subject", "Date"],
324	        }),
325	      `messages.get ${id}`
326	    );
327	    const labelIds = msg.data.labelIds ?? [];
328	    // Skip drafts — not a sent or received email.
329	    if (labelIds.includes("DRAFT")) continue;
330	
331	    const headers = msg.data.payload?.headers;
332	    const fromAddrs = addressesIn(headerValue(headers, "from"));
333	    const subject =
334	      decodeRFC2047(headerValue(headers, "subject")).trim() || "(no subject)";
335	    const ts = Number(msg.data.internalDate ?? 0);
336	    const dateStr = new Date(ts).toISOString().slice(0, 10);
337	    const threadId = msg.data.threadId ?? "";
338	    const messageId = msg.data.id ?? "";
339	    const direction = deriveDirection(
340	      labelIds,
341	      fromAddrs,
342	      contactEmails,
343	      contact.category
344	    );
345	
346	    entries.push({
347	      ts,
348	      dateStr,
349	      subject,
350	      direction,
351	      threadId,
352	      messageId,
353	      link: `https://mail.google.com/mail/u/0/#all/${messageId}?authuser=mark@felicisholdings.com`,
354	    });
355	  }
356	
357	  // Newest first, by exact timestamp.
358	  entries.sort((a, b) => b.ts - a.ts);
359	  return { entries, capped };
360	}
361	
362	// ─── Dry-run report ──────────────────────────────────────────────────────────
363	
364	function renderEntry(e: ProposedEntry): string {
365	  const lines = [`- **Subject:** ${e.subject}`, `  - Direction: ${e.direction}`];
366	  if (e.summary) lines.push(`  - Summary: ${e.summary}`);
367	  lines.push(`  - Thread: ${e.threadId}`);
368	  lines.push(`  - Message: ${e.messageId}`);
369	  lines.push(`  - Link: ${e.link}`);
370	  return lines.join("\n");
371	}
372	
373	// Every contact file across all categories, alphabetical (stable resume order).
374	function discoverAllContacts(): string[] {
375	  const files: string[] = [];
376	  for (const dir of ["client", "colleagues", "friends"]) {
377	    const abs = path.join(ROOT, dir);
378	    if (!fs.existsSync(abs)) continue;
379	    for (const f of fs.readdirSync(abs)) {
380	      if (f.endsWith(".md")) files.push(`${dir}/${f}`);
381	    }
382	  }
383	  return files.sort();
384	}
385	
386	async function main() {
387	  const rawArgs = process.argv.slice(2);
388	  if (rawArgs.includes("--help")) {
389	    console.error(
390	      "Usage: npm run gmail-sync -- [contact.md ...]\n" +
391	        "With no file args, scans ALL contacts in client/, colleagues/, friends/.\n" +
392	        "By default: searches Gmail, generates summaries, and WRITES the files (advances last_searched).\n" +
393	        "  --dry-run       read-only preview — write nothing\n" +
394	        "  --no-summarize  skip the local-model Summary line"
395	    );
396	    process.exit(0);
397	  }
398	  // Default behavior: summarize + write. Opt out per run.
399	  const writeFlag = !rawArgs.includes("--dry-run");
400	  const summarizeFlag = !rawArgs.includes("--no-summarize");
401	  const fileArgs = rawArgs.filter((a) => !a.startsWith("--"));
402	  const contactFiles = fileArgs.length > 0 ? fileArgs : discoverAllContacts();
403	  if (contactFiles.length === 0) {
404	    console.error("No contact files found.");
405	    process.exit(1);
406	  }
407	  if (fileArgs.length === 0) {
408	    console.error(`No files given — scanning all ${contactFiles.length} contacts.`);
409	  }
410	
411	  const today = new Date().toISOString().slice(0, 10);
412	  console.error("Authorizing (read-only)...");
413	  const auth = await authorize();
414	  const gmail = google.gmail({ version: "v1", auth });
415	
416	  for (const arg of contactFiles) {
417	    const contact = parseContact(arg);
418	    console.log(`\n${"═".repeat(72)}`);
419	    console.log(`Contact: ${contact.filePath}  [${contact.category}]`);
420	    console.log(`Addresses: ${contact.emails.join(", ") || "(none!)"}`);
421	    const after = effectiveAfter(contact, today);
422	    console.log(
423	      `Search bound: after ${after} ${
424	        contact.lastSearched
425	          ? "(incremental, from last_searched)"
426	          : `(first run, ${YEARS_BACK[contact.category] ?? 3}yr ${contact.category} floor)`
427	      }`
428	    );
429	
430	    if (contact.emails.length === 0) {
431	      console.log("⚠️  No addresses in frontmatter — skipping.");
432	      continue;
433	    }
434	
435	    const { entries, capped } = await searchContact(gmail, contact, today);
436	    if (capped) {
437	      console.log(
438	        `⚠️  Hit the ${MAX_MESSAGES_PER_CONTACT}-message safety cap — results truncated.`
439	      );
440	    }
441	
442	    // Split into genuinely-new vs already-present (dedup).
443	    const fresh: ProposedEntry[] = [];
444	    let already = 0;
445	    for (const e of entries) {
446	      if (contact.existingMessageIds.has(e.messageId)) {
447	        already++;
448	        continue;
449	      }
450	      if (contact.existingLegacyKeys.has(legacyKey(e))) {
451	        already++;
452	        continue;
453	      }
454	      fresh.push(e);
455	    }
456	
457	    console.log(
458	      `Found ${entries.length} message(s): ${fresh.length} new, ${already} already recorded.`
459	    );
460	    console.log(
461	      `${writeFlag ? "Setting" : "Would set"} last_searched: ${today} (currently ${
462	        contact.lastSearched ?? "unset"
463	      })`
464	    );
465	
466	    if (fresh.length > 0) {
467	      if (summarizeFlag) {
468	        console.error(
469	          `  Summarizing ${fresh.length} message(s) locally with Ollama (${OLLAMA_MODEL})...`
470	        );
471	        for (let i = 0; i < fresh.length; i++) {
472	          const e = fresh[i];
473	          const rawRes = await withBackoff(
474	            () =>
475	              gmail.users.messages.get({ userId: "me", id: e.messageId, format: "raw" }),
476	            `messages.get raw ${e.messageId}`
477	          );
478	          const summary = await summarize({
479	            rawBase64url: rawRes.data.raw ?? "",
480	            direction: e.direction,
481	            category: contact.category,
482	            firstName: contact.firstName,
483	            subject: e.subject,
484	          });
485	          if (summary) e.summary = summary;
486	          process.stderr.write(`\r  summarized ${i + 1}/${fresh.length}`);
487	        }
488	        process.stderr.write("\n");
489	      }
490	
491	      console.log(`\n--- ${writeFlag ? "New" : "Proposed new"} entries (newest first) ---`);
492	      let curDate = "";
493	      for (const e of fresh) {
494	        if (e.dateStr !== curDate) {
495	          curDate = e.dateStr;
496	          console.log(`\n### ${curDate}`);
497	        }
498	        console.log(renderEntry(e));
499	      }
500	    } else {
501	      console.log("→ No new entries to add.");
502	    }
503	
504	    if (writeFlag) {
505	      const abs = path.isAbsolute(arg) ? arg : path.join(ROOT, arg);
506	      const original = fs.readFileSync(abs, "utf-8");
507	      // Pass ALL fetched entries — mergeContact dedups against the file itself.
508	      const result = mergeContact(original, entries, today);
509	      if (result.status === "skipped-malformed") {
510	        console.log(
511	          `\n⚠️  SKIPPED (no clean "## Mark's Email History" heading) — fix by hand: ${arg}`
512	        );
513	      } else if (result.content !== original) {
514	        fs.writeFileSync(abs, result.content, "utf-8");
515	        console.log(`\n✍️  Wrote ${result.added} new entr(ies) → ${arg}`);
516	      } else {
517	        console.log(`\n= No file change → ${arg}`);
518	      }
519	    }
520	  }
521	
522	  console.log(`\n${"═".repeat(72)}`);
523	  console.log(
524	    writeFlag
525	      ? "Done — changes written to the contact files above."
526	      : "DRY RUN (--dry-run) — nothing was written."
527	  );
528	}
529	
530	main().catch((err) => {
531	  console.error("\n❌  gmail-sync failed:\n");
532	  console.error(err?.message || err);
533	  process.exit(1);
534	});
