import * as fs from "node:fs";
import * as path from "node:path";
import { google, gmail_v1 } from "googleapis";
import { authorize } from "./gmail-auth";
import { summarize, OLLAMA_MODEL } from "./summarize";
import { mergeContact } from "./merge";

// Slice 2 — Incremental per-contact search, READ-ONLY DRY-RUN.
//
// For each contact file passed as an argument, search Mark's Gmail for the
// contact's address(es), derive direction, dedup against entries already in the
// file, and PRINT the proposed new "Mark's Email History" entries plus the
// last_searched date that *would* be written. Writes nothing.
//
//   env "$(op environment read <item-id>)" npm run gmail-sync -- friends/blyth-don.md ...
//
// First run (no last_searched in frontmatter) searches all history, ignoring
// last_updated. Once last_searched exists it bounds the query with after:.

const ROOT = path.resolve(__dirname, "..");

// How far back the FIRST run reaches, per category, so an initial scan of a
// decades-deep mailbox doesn't take forever. Incremental runs ignore this — they
// are bounded by last_searched instead.
const YEARS_BACK: Record<string, number> = {
  client: 3,
  colleague: 3,
  friend: 10,
};

// Safety cap so a mis-built query can't page forever; we log if we hit it.
const MAX_MESSAGES_PER_CONTACT = 2000;

// Retry Gmail calls on rate-limit / transient errors with exponential backoff.
async function withBackoff<T>(fn: () => Promise<T>, label: string): Promise<T> {
  const maxRetries = 6;
  let delay = 500;
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn();
    } catch (err: unknown) {
      const e = err as {
        code?: number;
        response?: { status?: number };
        errors?: Array<{ reason?: string }>;
      };
      const status = e.code ?? e.response?.status;
      const reason = e.errors?.[0]?.reason ?? "";
      const retryable =
        status === 429 ||
        status === 500 ||
        status === 503 ||
        (status === 403 && /rateLimit|userRateLimit|quota/i.test(reason));
      if (!retryable || attempt >= maxRetries) throw err;
      const wait = delay + Math.floor(Math.random() * 250);
      console.error(
        `  ⏳ ${label}: ${status} ${reason} — retry ${attempt + 1}/${maxRetries} in ${wait}ms`
      );
      await new Promise((r) => setTimeout(r, wait));
      delay = Math.min(delay * 2, 16000);
    }
  }
}

// ─── Contact file parsing ────────────────────────────────────────────────────

interface Contact {
  filePath: string;
  category: string; // client | friend | colleague
  firstName: string | null; // for name-led summaries
  emails: string[]; // lowercased
  lastSearched: string | null; // YYYY-MM-DD or null
  existingMessageIds: Set<string>; // Gmail hex ids already recorded
  existingLegacyKeys: Set<string>; // date|subject|direction|thread for old entries
}

// Match on a path *segment* so both relative ("friends/x.md") and absolute
// paths work — the earlier "/friends/" substring test missed relative args.
function categoryFor(contactPath: string): string {
  const segs = contactPath.replace(/\\/g, "/").split("/");
  if (segs.includes("friends")) return "friend";
  if (segs.includes("colleagues")) return "colleague";
  return "client";
}

function unquote(s: string): string {
  return s.trim().replace(/^["']|["']$/g, "").trim();
}

function parseContact(contactPath: string): Contact {
  const abs = path.isAbsolute(contactPath)
    ? contactPath
    : path.join(ROOT, contactPath);
  const raw = fs.readFileSync(abs, "utf-8");

  const fmMatch = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!fmMatch) throw new Error(`No YAML frontmatter in ${contactPath}`);
  const fmLines = fmMatch[1].split(/\r?\n/);

  const emails: string[] = [];
  let lastSearched: string | null = null;
  let firstName: string | null = null;

  for (let i = 0; i < fmLines.length; i++) {
    const line = fmLines[i];
    const fn = line.match(/^first_name:\s*(.+)$/);
    if (fn) {
      firstName = unquote(fn[1]) || null;
      continue;
    }
    const single = line.match(/^email:\s*(.+)$/);
    if (single) {
      const v = unquote(single[1]);
      if (v.includes("@")) emails.push(v.toLowerCase());
      continue;
    }
    if (/^emails:\s*$/.test(line)) {
      for (let j = i + 1; j < fmLines.length; j++) {
        const item = fmLines[j].match(/^\s*-\s*(.+)$/);
        if (!item) break;
        const v = unquote(item[1]);
        if (v.includes("@")) emails.push(v.toLowerCase());
      }
      continue;
    }
    const ls = line.match(/^last_searched:\s*(.+)$/);
    if (ls) lastSearched = unquote(ls[1]) || null;
  }

  // Existing entries: collect Gmail message ids and legacy dedup keys from the
  // "## Mark's Email History" section only.
  const existingMessageIds = new Set<string>();
  const existingLegacyKeys = new Set<string>();
  const markSection = raw.split(/^##\s+Mark's Email History\s*$/m)[1];
  if (markSection) {
    // Cut it off at the next H2 (e.g. "## Email History").
    const section = markSection.split(/^##\s+/m)[0];
    let curDate = "";
    let curSubject = "";
    let curDirection = "";
    let curThread = "";
    let curMessage = "";
    const flushLegacy = () => {
      if (curSubject && !curMessage) {
        existingLegacyKeys.add(
          `${curDate}|${curSubject}|${curDirection}|${curThread}`
        );
      }
      curSubject = curDirection = curThread = curMessage = "";
    };
    for (const line of section.split(/\r?\n/)) {
      const dateM = line.match(/^###\s+(\d{4}-\d{2}-\d{2})/);
      if (dateM) {
        flushLegacy();
        curDate = dateM[1];
        continue;
      }
      const subjM = line.match(/^-\s+\*\*Subject:\*\*\s*(.+?)\s*$/);
      if (subjM) {
        flushLegacy();
        curSubject = subjM[1];
        continue;
      }
      const dirM = line.match(/^\s*-\s*Direction:\s*(.+?)\s*$/);
      if (dirM) curDirection = dirM[1];
      const thrM = line.match(/^\s*-\s*Thread:\s*(.+?)\s*$/);
      if (thrM) curThread = thrM[1];
      const msgM = line.match(/^\s*-\s*Message:\s*(.+?)\s*$/);
      if (msgM) {
        curMessage = msgM[1];
        existingMessageIds.add(curMessage);
      }
    }
    flushLegacy();
  }

  return {
    filePath: contactPath,
    category: categoryFor(contactPath),
    firstName,
    emails,
    lastSearched,
    existingMessageIds,
    existingLegacyKeys,
  };
}

// ─── Header helpers ──────────────────────────────────────────────────────────

function decodeRFC2047(s: string): string {
  return s.replace(
    /=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g,
    (_m, charset, enc, encoded) => {
      try {
        if (enc.toUpperCase() === "B") {
          return Buffer.from(encoded, "base64").toString(
            charset.toLowerCase() === "utf-8" ? "utf-8" : "latin1"
          );
        }
        return encoded
          .replace(/_/g, " ")
          .replace(/=([0-9A-Fa-f]{2})/g, (_x: string, h: string) =>
            String.fromCharCode(parseInt(h, 16))
          );
      } catch {
        return encoded;
      }
    }
  );
}

// Extract lowercased email addresses from a header value.
function addressesIn(headerValue: string): string[] {
  const out: string[] = [];
  const re = /[\w.+\-]+@[\w.\-]+\.\w+/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(headerValue)) !== null) out.push(m[0].toLowerCase());
  return out;
}

function headerValue(
  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
  name: string
): string {
  const h = headers?.find((x) => (x.name ?? "").toLowerCase() === name);
  return h?.value ?? "";
}

// ─── Direction ───────────────────────────────────────────────────────────────

// Mark sent it (Gmail SENT label, authoritative across all of Mark's historical
// addresses) → "To {cat}". Else contact is the sender → "From {cat}". Else Mark
// is only a recipient on a thread neither he nor the contact started → "CC'd".
function deriveDirection(
  labelIds: string[],
  fromAddrs: string[],
  contactEmails: Set<string>,
  category: string
): string {
  if (labelIds.includes("SENT")) return `To ${category}`;
  if (fromAddrs.some((a) => contactEmails.has(a))) return `From ${category}`;
  return "CC'd";
}

// ─── Proposed entry ──────────────────────────────────────────────────────────

interface ProposedEntry {
  ts: number; // internalDate ms, for exact ordering within a day
  dateStr: string;
  subject: string;
  direction: string;
  threadId: string;
  messageId: string;
  link: string;
  summary?: string; // filled by --summarize
}

function legacyKey(e: ProposedEntry): string {
  return `${e.dateStr}|${e.subject}|${e.direction}|${e.threadId}`;
}

// ─── Gmail search ────────────────────────────────────────────────────────────

// The lower bound for a contact's search: last_searched if we have one,
// otherwise the per-category first-run floor (today − N years). Returns
// YYYY-MM-DD.
function effectiveAfter(contact: Contact, today: string): string {
  if (contact.lastSearched) return contact.lastSearched;
  const years = YEARS_BACK[contact.category] ?? 3;
  const d = new Date(today);
  d.setFullYear(d.getFullYear() - years);
  return d.toISOString().slice(0, 10);
}

function buildQuery(contact: Contact, today: string): string {
  const addrs = contact.emails.join(" OR ");
  const clauses = `(from:(${addrs}) OR to:(${addrs}) OR cc:(${addrs}))`;
  const after = effectiveAfter(contact, today).replace(/-/g, "/"); // YYYY/MM/DD
  return `after:${after} ${clauses}`;
}

async function searchContact(
  gmail: gmail_v1.Gmail,
  contact: Contact,
  today: string
): Promise<{ entries: ProposedEntry[]; capped: boolean }> {
  const q = buildQuery(contact, today);
  const ids: { id: string; threadId: string }[] = [];
  let pageToken: string | undefined;
  let capped = false;

  do {
    const res = await withBackoff(
      () =>
        gmail.users.messages.list({
          userId: "me",
          q,
          maxResults: 500,
          pageToken,
        }),
      "messages.list"
    );
    for (const m of res.data.messages ?? []) {
      if (m.id && m.threadId) ids.push({ id: m.id, threadId: m.threadId });
    }
    pageToken = res.data.nextPageToken ?? undefined;
    if (ids.length >= MAX_MESSAGES_PER_CONTACT) {
      capped = true;
      break;
    }
  } while (pageToken);

  const contactEmails = new Set(contact.emails);
  const entries: ProposedEntry[] = [];

  for (const { id } of ids) {
    const msg = await withBackoff(
      () =>
        gmail.users.messages.get({
          userId: "me",
          id,
          format: "metadata",
          metadataHeaders: ["From", "To", "Cc", "Subject", "Date"],
        }),
      `messages.get ${id}`
    );
    const labelIds = msg.data.labelIds ?? [];
    // Skip drafts — not a sent or received email.
    if (labelIds.includes("DRAFT")) continue;

    const headers = msg.data.payload?.headers;
    const fromAddrs = addressesIn(headerValue(headers, "from"));
    const subject =
      decodeRFC2047(headerValue(headers, "subject")).trim() || "(no subject)";
    const ts = Number(msg.data.internalDate ?? 0);
    const dateStr = new Date(ts).toISOString().slice(0, 10);
    const threadId = msg.data.threadId ?? "";
    const messageId = msg.data.id ?? "";
    const direction = deriveDirection(
      labelIds,
      fromAddrs,
      contactEmails,
      contact.category
    );

    entries.push({
      ts,
      dateStr,
      subject,
      direction,
      threadId,
      messageId,
      link: `https://mail.google.com/mail/u/0/#all/${messageId}?authuser=mark@felicisholdings.com`,
    });
  }

  // Newest first, by exact timestamp.
  entries.sort((a, b) => b.ts - a.ts);
  return { entries, capped };
}

// ─── Dry-run report ──────────────────────────────────────────────────────────

function renderEntry(e: ProposedEntry): string {
  const lines = [`- **Subject:** ${e.subject}`, `  - Direction: ${e.direction}`];
  if (e.summary) lines.push(`  - Summary: ${e.summary}`);
  lines.push(`  - Thread: ${e.threadId}`);
  lines.push(`  - Message: ${e.messageId}`);
  lines.push(`  - Link: ${e.link}`);
  return lines.join("\n");
}

// Every contact file across all categories, alphabetical (stable resume order).
function discoverAllContacts(): string[] {
  const files: string[] = [];
  for (const dir of ["client", "colleagues", "friends"]) {
    const abs = path.join(ROOT, dir);
    if (!fs.existsSync(abs)) continue;
    for (const f of fs.readdirSync(abs)) {
      if (f.endsWith(".md")) files.push(`${dir}/${f}`);
    }
  }
  return files.sort();
}

async function main() {
  const rawArgs = process.argv.slice(2);
  if (rawArgs.includes("--help")) {
    console.error(
      "Usage: npm run gmail-sync -- [contact.md ...]\n" +
        "With no file args, scans ALL contacts in client/, colleagues/, friends/.\n" +
        "By default: searches Gmail, generates summaries, and WRITES the files (advances last_searched).\n" +
        "  --dry-run       read-only preview — write nothing\n" +
        "  --no-summarize  skip the local-model Summary line"
    );
    process.exit(0);
  }
  // Default behavior: summarize + write. Opt out per run.
  const writeFlag = !rawArgs.includes("--dry-run");
  const summarizeFlag = !rawArgs.includes("--no-summarize");
  const fileArgs = rawArgs.filter((a) => !a.startsWith("--"));
  const contactFiles = fileArgs.length > 0 ? fileArgs : discoverAllContacts();
  if (contactFiles.length === 0) {
    console.error("No contact files found.");
    process.exit(1);
  }
  if (fileArgs.length === 0) {
    console.error(`No files given — scanning all ${contactFiles.length} contacts.`);
  }

  const today = new Date().toISOString().slice(0, 10);
  console.error("Authorizing (read-only)...");
  const auth = await authorize();
  const gmail = google.gmail({ version: "v1", auth });

  for (const arg of contactFiles) {
    const contact = parseContact(arg);
    console.log(`\n${"═".repeat(72)}`);
    console.log(`Contact: ${contact.filePath}  [${contact.category}]`);
    console.log(`Addresses: ${contact.emails.join(", ") || "(none!)"}`);
    const after = effectiveAfter(contact, today);
    console.log(
      `Search bound: after ${after} ${
        contact.lastSearched
          ? "(incremental, from last_searched)"
          : `(first run, ${YEARS_BACK[contact.category] ?? 3}yr ${contact.category} floor)`
      }`
    );

    if (contact.emails.length === 0) {
      console.log("⚠️  No addresses in frontmatter — skipping.");
      continue;
    }

    const { entries, capped } = await searchContact(gmail, contact, today);
    if (capped) {
      console.log(
        `⚠️  Hit the ${MAX_MESSAGES_PER_CONTACT}-message safety cap — results truncated.`
      );
    }

    // Split into genuinely-new vs already-present (dedup).
    const fresh: ProposedEntry[] = [];
    let already = 0;
    for (const e of entries) {
      if (contact.existingMessageIds.has(e.messageId)) {
        already++;
        continue;
      }
      if (contact.existingLegacyKeys.has(legacyKey(e))) {
        already++;
        continue;
      }
      fresh.push(e);
    }

    console.log(
      `Found ${entries.length} message(s): ${fresh.length} new, ${already} already recorded.`
    );
    console.log(
      `${writeFlag ? "Setting" : "Would set"} last_searched: ${today} (currently ${
        contact.lastSearched ?? "unset"
      })`
    );

    if (fresh.length > 0) {
      if (summarizeFlag) {
        console.error(
          `  Summarizing ${fresh.length} message(s) locally with Ollama (${OLLAMA_MODEL})...`
        );
        for (let i = 0; i < fresh.length; i++) {
          const e = fresh[i];
          const rawRes = await withBackoff(
            () =>
              gmail.users.messages.get({ userId: "me", id: e.messageId, format: "raw" }),
            `messages.get raw ${e.messageId}`
          );
          const summary = await summarize({
            rawBase64url: rawRes.data.raw ?? "",
            direction: e.direction,
            category: contact.category,
            firstName: contact.firstName,
            subject: e.subject,
          });
          if (summary) e.summary = summary;
          process.stderr.write(`\r  summarized ${i + 1}/${fresh.length}`);
        }
        process.stderr.write("\n");
      }

      console.log(`\n--- ${writeFlag ? "New" : "Proposed new"} entries (newest first) ---`);
      let curDate = "";
      for (const e of fresh) {
        if (e.dateStr !== curDate) {
          curDate = e.dateStr;
          console.log(`\n### ${curDate}`);
        }
        console.log(renderEntry(e));
      }
    } else {
      console.log("→ No new entries to add.");
    }

    if (writeFlag) {
      const abs = path.isAbsolute(arg) ? arg : path.join(ROOT, arg);
      const original = fs.readFileSync(abs, "utf-8");
      // Pass ALL fetched entries — mergeContact dedups against the file itself.
      const result = mergeContact(original, entries, today);
      if (result.status === "skipped-malformed") {
        console.log(
          `\n⚠️  SKIPPED (no clean "## Mark's Email History" heading) — fix by hand: ${arg}`
        );
      } else if (result.content !== original) {
        fs.writeFileSync(abs, result.content, "utf-8");
        console.log(`\n✍️  Wrote ${result.added} new entr(ies) → ${arg}`);
      } else {
        console.log(`\n= No file change → ${arg}`);
      }
    }
  }

  console.log(`\n${"═".repeat(72)}`);
  console.log(
    writeFlag
      ? "Done — changes written to the contact files above."
      : "DRY RUN (--dry-run) — nothing was written."
  );
}

main().catch((err) => {
  console.error("\n❌  gmail-sync failed:\n");
  console.error(err?.message || err);
  process.exit(1);
});

