13	  messageId: string;
14	  link: string;
15	  summary?: string;
16	}
17	
18	// Parsed form of an entry already in the file — legacy Cowork entries may lack
19	// message id / link, so those are optional.
20	interface Entry {
21	  ts: number;
22	  dateStr: string;
23	  subject: string;
24	  direction: string;
25	  summary?: string;
26	  threadId?: string;
27	  messageId?: string;
28	  link?: string;
29	}
30	
31	export interface MergeResult {
32	  content: string;
33	  added: number;
34	  status: "written" | "skipped-malformed";
35	}
36	
37	const MARK_HEADING_RE = /^##[ \t]+Mark's Email History[ \t]*$/m;
38	const NEXT_H2_RE = /^##[ \t]+/m;
39	
40	function parseEntries(markBody: string): Entry[] {
41	  const entries: Entry[] = [];
42	  let curDate = "";
43	  let cur: Entry | null = null;
44	
45	  const push = () => {
46	    if (cur) entries.push(cur);
47	    cur = null;
48	  };
49	
50	  for (const line of markBody.split(/\r?\n/)) {
51	    const date = line.match(/^###\s+(\d{4}-\d{2}-\d{2})/);
52	    if (date) {
53	      push();
54	      curDate = date[1];
55	      continue;
56	    }
57	    const subj = line.match(/^-\s+\*\*Subject:\*\*\s*(.+?)\s*$/);
58	    if (subj) {
59	      push();
60	      cur = {
61	        ts: Date.parse(`${curDate}T00:00:00Z`),
62	        dateStr: curDate,
63	        subject: subj[1],
64	        direction: "",
65	      };
66	      continue;
67	    }
68	    if (!cur) continue;
69	    const dir = line.match(/^\s*-\s*Direction:\s*(.+?)\s*$/);
70	    if (dir) cur.direction = dir[1];
71	    const sum = line.match(/^\s*-\s*Summary:\s*(.+?)\s*$/);
72	    if (sum) cur.summary = sum[1];
73	    const thr = line.match(/^\s*-\s*Thread:\s*(.+?)\s*$/);
74	    if (thr) cur.threadId = thr[1];
75	    const msg = line.match(/^\s*-\s*Message:\s*(.+?)\s*$/);
76	    if (msg) cur.messageId = msg[1];
77	    const lnk = line.match(/^\s*-\s*Link:\s*(.+?)\s*$/);
78	    if (lnk) cur.link = lnk[1];
79	  }
80	  push();
81	  return entries;
82	}
83	
84	function renderEntry(e: Entry): string[] {
85	  const lines = [`- **Subject:** ${e.subject}`, `  - Direction: ${e.direction}`];
86	  if (e.summary) lines.push(`  - Summary: ${e.summary}`);
87	  if (e.threadId) lines.push(`  - Thread: ${e.threadId}`);
88	  if (e.messageId) lines.push(`  - Message: ${e.messageId}`);
89	  if (e.link) lines.push(`  - Link: ${e.link}`);
90	  return lines;
91	}
92	
93	function renderSection(entries: Entry[]): string {
94	  const sorted = [...entries].sort((a, b) => b.ts - a.ts);
95	  const lines: string[] = [];
96	  let curDate = "";
97	  for (const e of sorted) {
98	    if (e.dateStr !== curDate) {
99	      curDate = e.dateStr;
100	      lines.push(`### ${curDate}`);
101	    }
102	    lines.push(...renderEntry(e));
103	    lines.push("");
104	  }
105	  return lines.join("\n");
106	}
107	
108	// Update-or-insert frontmatter fields inside the leading `---` block of `head`,
109	// leaving every other line (name, email/emails list) untouched.
110	function updateFrontmatter(head: string, fields: Record<string, string>): string {
111	  const fm = head.match(/^---\r?\n([\s\S]*?)(\r?\n)---/);
112	  if (!fm) return head;
113	  let inner = fm[1];
114	  for (const [key, value] of Object.entries(fields)) {
115	    const re = new RegExp(`^${key}:.*$`, "m");
116	    if (re.test(inner)) inner = inner.replace(re, `${key}: ${value}`);
117	    else inner = `${inner}\n${key}: ${value}`;
118	  }
119	  return head.slice(0, fm.index! ) + `---\n${inner}\n---` + head.slice(fm.index! + fm[0].length);
120	}
121	
122	export function mergeContact(
123	  existingContent: string,
124	  fetched: FetchedEntry[],
125	  today: string
126	): MergeResult {
127	  const headingMatch = existingContent.match(MARK_HEADING_RE);
128	  if (!headingMatch || headingMatch.index === undefined) {
129	    return { content: existingContent, added: 0, status: "skipped-malformed" };
130	  }
131	
132	  const headingStart = headingMatch.index;
133	  const afterHeading = headingStart + headingMatch[0].length;
134	
135	  // The mbox section (if any) starts at the next H2 after the Mark heading.
136	  const rest = existingContent.slice(afterHeading);
137	  const nextH2 = rest.match(NEXT_H2_RE);
138	  const markBody =
139	    nextH2 && nextH2.index !== undefined ? rest.slice(0, nextH2.index) : rest;
140	  const tail =
141	    nextH2 && nextH2.index !== undefined ? rest.slice(nextH2.index) : "";
142	
143	  const rawHead = existingContent.slice(0, headingStart);
144	
145	  const existing = parseEntries(markBody);
146	  const existingIds = new Set(
147	    existing.map((e) => e.messageId).filter((id): id is string => !!id)
148	  );
149	  // Legacy entries (no Message id) dedup on an exact 4-tuple. Exact only — a
150	  // looser match risks silently dropping a real message.
151	  const legacyKey = (e: {
152	    dateStr: string;
153	    subject: string;
154	    direction: string;
155	    threadId?: string;
156	  }) => `${e.dateStr}|${e.subject}|${e.direction}|${e.threadId ?? ""}`;
157	  const legacyKeys = new Set(
158	    existing.filter((e) => !e.messageId).map(legacyKey)
159	  );
160	  const fresh = fetched.filter(
161	    (f) => !existingIds.has(f.messageId) && !legacyKeys.has(legacyKey(f))
162	  );
163	  const merged: Entry[] = [...existing, ...fresh];
164	  const added = fresh.length;
165	
166	  // last_searched always advances; last_updated only when we actually changed entries.
167	  const fields: Record<string, string> = { last_searched: today };
168	  if (added > 0) fields.last_updated = today;
169	  const head = updateFrontmatter(rawHead, fields);
170	
171	  // Nothing new: keep the section (entries or placeholder) byte-for-byte and only
172	  // bump last_searched. Otherwise regenerate the section from the merged entries.
173	  const heading = headingMatch[0];
174	  const body = added > 0 ? `\n\n${renderSection(merged)}\n` : markBody;
175	  let content = `${head}${heading}${body}${tail}`;
176	  // When Mark's section is the last thing in the file (friends/colleagues have no
177	  // "## Email History"), collapse the trailing blank line to a single newline.
178	  if (tail === "") content = content.replace(/\n+$/, "\n");
179	
180	  return { content, added, status: "written" };
181	}
