function headerValue(
  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
  name: string
): string {
  const h = headers?.find((x) => (x.name ?? "").toLowerCase() === name);
  return h?.value ?? "";
}

// Split a header's address list on commas that aren't inside a quoted display
// name (e.g. `"Harris, Josh" <josh@x.com>, else@y.com`).
function splitAddressList(headerValue: string): string[] {
  const parts: string[] = [];
  let quoted = false;
  let cur = "";
  for (const ch of headerValue) {
    if (ch === '"') quoted = !quoted;
    if (ch === "," && !quoted) {
      parts.push(cur);
      cur = "";
    } else {
      cur += ch;
    }
  }
  if (cur.trim()) parts.push(cur);
  return parts;
}

// Pull the display name paired with a specific address out of a From/To/Cc
// header, e.g. `"Josh Harris" <josh@x.com>` → "Josh Harris".
function displayNameFor(headerVal: string, wantedEmails: Set<string>): string | null {
  for (const part of splitAddressList(decodeRFC2047(headerVal))) {
    const m = part.match(/^\s*"?([^"<]*?)"?\s*<\s*([^>]+?)\s*>\s*$/);
    if (!m) continue;
    const name = m[1].trim();
    const email = m[2].trim().toLowerCase();
    if (name && wantedEmails.has(email)) return name;
  }
  return null;
}

// Look across From/To/Cc for a display name belonging to one of the contact's
// addresses — used to backfill a name for contacts recorded with only an email.
function findDisplayName(
  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
  contactEmails: Set<string>
): string | null {
  for (const field of ["from", "to", "cc"]) {
    const name = displayNameFor(headerValue(headers, field), contactEmails);
    if (name) return name;
  }
  return null;
}

