import * as path from "node:path";
import * as fs from "node:fs";
import * as fsp from "node:fs/promises";
import * as http from "node:http";
import type { AddressInfo } from "node:net";
import { exec } from "node:child_process";
import { google } from "googleapis";

// Shared Gmail OAuth for the CRM sync tool.
//
// Desktop-app loopback flow, read-only scope. The OAuth client secret is never
// written to disk: it is read from GMAIL_OAUTH_SECRET in the environment,
// supplied by 1Password at run time — e.g.
//   env "$(op environment read <item-id>)" npm run gmail-login
// The secret stays in memory and is needed each run to refresh access tokens.
// Only the refresh token is persisted, to .secrets/token.json — useless without it.

// Use the exact instance type of the OAuth2 constructor we call. This is the
// same class google.gmail() expects; the top-level google-auth-library ships a
// structurally distinct copy, so referencing that here causes private-property
// clashes.
type AuthClient = InstanceType<typeof google.auth.OAuth2>;

const ROOT = path.resolve(__dirname, "..");
const SECRETS_DIR = path.join(ROOT, ".secrets");
export const TOKEN_PATH = path.join(SECRETS_DIR, "token.json");

// Public identifier — safe to commit. Only the secret is sensitive.
const CLIENT_ID =
  "672392946834-ebml9v07rgoghkfl9hlc5lprq83otj1j.apps.googleusercontent.com";

// Read-only: the tool reads mail and writes markdown locally. Nothing more.
const SCOPES = ["https://www.googleapis.com/auth/gmail.readonly"];

// Obtain the OAuth client secret from the environment, where 1Password injects
// it. Never read from or written to disk.
function readClientSecret(): string {
  const secret = process.env.GMAIL_OAUTH_SECRET?.trim();
  const runHint =
    '  env "$(op environment read <item-id>)" npm run gmail-login';
  if (!secret) {
    throw new Error(`GMAIL_OAUTH_SECRET is not set. Run through 1Password:\n${runHint}`);
  }
  if (secret.startsWith("op://")) {
    throw new Error(
      `GMAIL_OAUTH_SECRET is an unresolved 1Password reference (${secret}).\n` +
        `Run the command through \`op run\` so 1Password resolves it:\n${runHint}`
    );
  }
  return secret;
}

// The only persisted artifact: the refresh token (no client secret).
function readSavedRefreshToken(): string | null {
  try {
    const raw = fs.readFileSync(TOKEN_PATH, "utf-8");
    return JSON.parse(raw).refresh_token ?? null;
  } catch {
    return null;
  }
}

async function saveRefreshToken(refreshToken: string): Promise<void> {
  await fsp.mkdir(SECRETS_DIR, { recursive: true });
  await fsp.writeFile(
    TOKEN_PATH,
    JSON.stringify({ refresh_token: refreshToken }, null, 2),
    "utf-8"
  );
}

function openBrowser(url: string): void {
  const cmd =
    process.platform === "darwin"
      ? "open"
      : process.platform === "win32"
        ? "start"
        : "xdg-open";
  exec(`${cmd} "${url}"`);
}

// One-time interactive consent over a loopback server on an ephemeral port.
// Desktop OAuth clients accept any http://127.0.0.1:<port> redirect without
// pre-registration.
function runLoopbackConsent(
  clientSecret: string
): Promise<{ client: AuthClient; refreshToken: string }> {
  return new Promise((resolve, reject) => {
    const server = http.createServer();
    server.on("error", reject);

    server.listen(0, "127.0.0.1", () => {
      const port = (server.address() as AddressInfo).port;
      const redirectUri = `http://127.0.0.1:${port}/oauth2callback`;
      const client = new google.auth.OAuth2(CLIENT_ID, clientSecret, redirectUri);

      const authUrl = client.generateAuthUrl({
        access_type: "offline",
        scope: SCOPES,
        prompt: "consent", // force a refresh_token even on re-consent
      });

      server.on("request", async (req, res) => {
        try {
          const url = new URL(req.url ?? "/", redirectUri);
          const err = url.searchParams.get("error");
          const code = url.searchParams.get("code");

          if (err) {
            res.end(`Authorization error: ${err}`);
            server.close();
            reject(new Error(`Google returned error: ${err}`));
            return;
          }
          if (!code) {
            res.writeHead(404);
            res.end();
            return;
          }

          res.end(
            "✅ Gmail authorized — you can close this tab and return to the terminal."
          );
          server.close();

          const { tokens } = await client.getToken(code);
          if (!tokens.refresh_token) {
            reject(
              new Error(
                "No refresh_token returned. Revoke the app's prior grant at " +
                  "https://myaccount.google.com/permissions and retry."
              )
            );
            return;
          }
          client.setCredentials(tokens);
          resolve({ client, refreshToken: tokens.refresh_token });
        } catch (e) {
          server.close();
          reject(e);
        }
      });

      console.error(
        `\nOpening browser for Google consent...\nIf it doesn't open, visit:\n${authUrl}\n`
      );
      openBrowser(authUrl);
    });
  });
}

// Return an authorized OAuth2 client. The client secret is read every run (kept
// in memory only); the browser consent runs only when no refresh token is saved.
export async function authorize(): Promise<AuthClient> {
  const clientSecret = readClientSecret();
  const savedRefresh = readSavedRefreshToken();

  if (savedRefresh) {
    const client = new google.auth.OAuth2(CLIENT_ID, clientSecret);
    client.setCredentials({ refresh_token: savedRefresh });
    return client;
  }

  const { client, refreshToken } = await runLoopbackConsent(clientSecret);
  await saveRefreshToken(refreshToken);
  return client;
}

